// The Vault page's live rows (app/vault/progress.js) as the page runs them:
// the real init (registered through lib/av), a stand-in EventSource, the
// page's own markup (generated by the Go test handlers/vault
// TestVaultPageFixtureIsCurrent) and the dashboard stream's own messages
// (handlers/resource TestVaultStatusFixturesAreCurrent). The badge's renderer
// has its own tests (statusBadge.test.js); these are about the row -- that it
// draws the status through that renderer into the badge the server rendered,
// and keeps what is the Vault page's own: the row's fill and percent, "Saved"
// for a vaulted torrent, the first cell's pulse, the token's renewal. It
// lives here and not next to progress.js because webpack builds every .js
// under app/ as an entry.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { JSDOM } from 'jsdom';

const PAGE = readFileSync(new URL('./__fixtures__/vault-page.html', import.meta.url), 'utf8');
const STATES = JSON.parse(readFileSync(new URL('./__fixtures__/vault-status-states.json', import.meta.url), 'utf8'));
const S = Object.fromEntries(STATES.map((s) => [s.design, s]));
// The fixture's two live rows (handlers/vault fixturePledges): the first
// row, and the table's last.
const RID = '4897aacef168307328e121694dcdb8407e6d62cc';
const RID2 = '5d0c1a9e3b7f2e4a6c8d0f1b3a5c7e9f2b4d6a8c';

globalThis.__SUPPORTED_LOCALES__ = ['en', 'ru'];
const dom = new JSDOM(`<!doctype html><html lang="ru"><body>${PAGE}</body></html>`, {
    url: 'https://webtor.io/ru/vault?debug_status=vaulting&progress=58&peers=12&seeders=0&availability=0.73&debug_missing=holes&unrelated=1',
});
global.window = dom.window;
global.document = dom.window.document;

const sources = [];
global.EventSource = class {
    static CLOSED = 2;
    constructor(url) { this.url = url; this.closed = false; this.readyState = 1; sources.push(this); }
    close() { this.closed = true; this.readyState = 2; }
    // Test side: what the server would send.
    message(status) { this.onmessage({ data: JSON.stringify(status) }); }
    refuse() { this.readyState = 2; this.onerror({}); }
};

// lib/av registers the init against the element holding the script: the
// table's async-layout wrapper, where views/vault/index.html puts it.
const root = document.getElementById('vault-pledges');
const script = document.createElement('script');
root.appendChild(script);
Object.defineProperty(document, 'currentScript', { configurable: true, get: () => script });
await import('../app/vault/progress.js');
const [target, init, destroy] = window.av[0];
await init.call(target);

const rowOf = (rid) => document.querySelector(`[data-vault-progress][data-resource-id="${rid}"]`);
const row = () => rowOf(RID);
const badgeOf = (rid) => rowOf(rid).querySelector('[data-tx-badge]');
const badge = () => badgeOf(RID);
const fresh = (html) => new JSDOM(`<!doctype html><body>${html}</body>`).window.document.querySelector('[data-tx-badge]');
function snapshot(el) {
    return {
        tone: el.getAttribute('data-tone'),
        icon: el.getAttribute('data-icon'),
        pulse: el.hasAttribute('data-pulse'),
        use: el.querySelector('.tx-bi use').getAttribute('href'),
        title: el.querySelector('.badge-text').getAttribute('title'),
        text: el.textContent.replace(/\s+/g, ' ').trim(),
    };
}
// The pill the page renders for a pledge already vaulted: what a live row
// ends as.
const savedPill = () => document.querySelectorAll('tbody tr')[1].querySelector('[data-tx-badge]');
// Each live row's badge as the server rendered it, before any message.
const INITIAL = [RID, RID2].map((rid) => snapshot(badgeOf(rid)));

test('one stream per live row: the dashboard\'s (no session), with its token and the page\'s debug preview', () => {
    assert.equal(target, root);
    assert.equal(sources.length, 2, 'the two live rows; the vaulted and the expiring rows open nothing');
    [RID, RID2].forEach((rid, i) => {
        const u = new URL(sources[i].url, 'https://webtor.io');
        assert.equal(u.pathname, `/ru/${rid}/status`);
        assert.equal(u.searchParams.get('_csrf'), 'csrf-token');
        assert.equal(u.searchParams.get('token'), 'status-token');
        assert.equal(u.searchParams.has('session'), false, 'no view, no viewer: the badge alone');
        assert.equal(u.searchParams.get('debug_status'), 'vaulting', 'dev preview params ride along');
        assert.equal(u.searchParams.get('availability'), '0.73');
        assert.equal(u.searchParams.get('debug_missing'), 'holes');
        assert.equal(u.searchParams.has('unrelated'), false, 'only the preview\'s own');
    });
});

test('before its first message a live row says statusview\'s "checking": a real state, not an empty pill', () => {
    // S.checking is the dashboard stream's badge for KeyChecking, generated
    // through the handler's own presentation -- the badge statusview gives a
    // torrent nothing has been asked about yet.
    for (const snap of INITIAL) {
        assert.deepEqual(snap, snapshot(fresh(S.checking.ssr)));
        assert.notEqual(snap.text, '', 'words: the pill is as tall as every other');
    }
});

test('every state: the row\'s badge is the server\'s, drawn in place into the same element', async () => {
    const el = badge();
    const before = [el, ...el.querySelectorAll('*')];
    const records = [];
    const mo = new dom.window.MutationObserver((r) => records.push(...r));
    mo.observe(row(), { childList: true, subtree: true });
    const live = STATES.filter((s) => s.status.state !== 'vaulted');
    for (const st of [...live, ...live.slice().reverse()]) {
        sources[0].message(st.status);
        await Promise.resolve();
        assert.equal(badge(), el, `${st.design}: the same badge`);
        assert.ok([el, ...el.querySelectorAll('*')].every((n, i) => n === before[i]), `${st.design}: the same nodes`);
        assert.deepEqual(snapshot(el), snapshot(fresh(st.ssr)), st.design);
    }
    mo.disconnect();
    const moved = records.filter((r) => r.target.closest('[data-tx-badge]') && [...r.addedNodes, ...r.removedNodes].some((n) => n.nodeType === 1));
    assert.deepEqual(moved, [], 'no element added to or removed from the badge');
    assert.equal(sources[0].closed, false);
});

test('the row\'s own: the fill and its percent while the transfer runs', () => {
    sources[0].message(S.vaulting_only.status);
    assert.match(row().style.backgroundImage, /64%/);
    const pct = row().querySelector('[data-vault-progress-pct]');
    assert.equal(pct.textContent, '64%');
    assert.equal(pct.classList.contains('hidden'), false);
    sources[0].message(S.vault_waiting.status);
    assert.equal(pct.classList.contains('hidden'), true, 'no percent where nothing is stored');
    assert.equal(row().querySelectorAll('[data-vault-progress-pct]').length, 1, 'one indicator, reused');
});

test('two rows, two streams: each draws into its own row\'s badge and fill, and leaves the other alone', () => {
    const pairs = [
        [S.vault_missing, S.caching_only],
        [S.noseed, S.vault_waiting],
        [S.vault_failed, S.paused],
    ];
    let second = INITIAL[1];
    for (const [a, b] of pairs) {
        sources[0].message(a.status);
        assert.deepEqual(snapshot(badgeOf(RID)), snapshot(fresh(a.ssr)), `row 1: ${a.design}`);
        assert.deepEqual(snapshot(badgeOf(RID2)), second, `row 2 untouched by row 1's ${a.design}`);
        sources[1].message(b.status);
        second = snapshot(fresh(b.ssr));
        assert.deepEqual(snapshot(badgeOf(RID2)), second, `row 2: ${b.design}`);
        assert.deepEqual(snapshot(badgeOf(RID)), snapshot(fresh(a.ssr)), `row 1 untouched by row 2's ${b.design}`);
    }
    sources[1].message(S.caching_only.status);
    assert.match(rowOf(RID2).style.backgroundImage, /43%/);
    sources[0].message(S.vaulting_only.status);
    assert.match(rowOf(RID).style.backgroundImage, /64%/);
    assert.match(rowOf(RID2).style.backgroundImage, /43%/, 'row 2\'s fill is its own');
});

test('a server from before `badge` (a rolling deploy, a rollback): the badge stays, and vaulted still ends as "Saved"', () => {
    const el = badgeOf(RID2);
    const before = snapshot(el);
    // What a replica without the badge sends: state, progress, label.
    sources[1].message({ state: 'vaulting', progress: 71, label: 'Сохраняется' });
    assert.deepEqual(snapshot(el), before, 'no badge made up from the state');
    assert.match(rowOf(RID2).style.backgroundImage, /71%/, 'the fill still moves');
    const icon = rowOf(RID2).querySelector('[data-vault-progress-icon]');
    sources[1].message({ state: 'vaulted', progress: 100, label: 'В Vault' });
    assert.deepEqual(snapshot(el), snapshot(savedPill()), 'the finished pledge\'s pill, not dots for good');
    assert.equal(badgeOf(RID2), el, 'still the same element');
    assert.equal(icon.classList.contains('vault-pulse'), false);
    assert.equal(sources[1].closed, true);
    assert.equal(sources[0].closed, false, 'the other row\'s stream stays');
});

test('vaulted: the badge the page renders for a vaulted pledge ("Saved"), the pulse settles, the stream closes', () => {
    const icon = row().querySelector('[data-vault-progress-icon]');
    assert.equal(icon.classList.contains('vault-pulse'), true);
    const el = badge();
    sources[0].message(S.vaulted_idle.status);
    const saved = savedPill();
    assert.equal(saved.textContent.trim(), 'Сохранён');
    assert.deepEqual(snapshot(el), snapshot(saved), 'the live row ends as the finished one is drawn');
    assert.equal(badge(), el, 'still the same element');
    assert.equal(icon.classList.contains('vault-pulse'), false);
    assert.equal(sources[0].closed, true);
});

test('a refused stream (its token expired) reloads the table the async way, at most once a minute', async () => {
    await destroy.call(target);
    await init.call(target);
    assert.equal(sources.length, 4, 'a stream for each live row again');
    const [a, b] = sources.slice(2);
    let reloads = 0;
    root.reload = () => { reloads++; };
    a.refuse();
    assert.equal(reloads, 1);
    assert.equal(a.closed && b.closed, true, 'its own streams closed before the swap');
    await init.call(target);
    sources[4].refuse();
    assert.equal(reloads, 1, 'not again within the minute');
});
